INSERT INTO "workflow_host_conclusions" VALUES('conclusion-00000000-0000-0000-0000-000000000085','00000000-0000-0000-0000-000000000082',NULL,3,1,'cancelled','Lead concludes cancelled fixture work',NULL,NULL,NULL,'lead','00000000-0000-0000-0000-000000000079','conclude-15c65895558f27de559427dde123d184','2026-01-01T00:00:48.000Z');
INSERT INTO "workflow_host_conclusions" VALUES('conclusion-00000000-0000-0000-0000-000000000103','00000000-0000-0000-0000-0000000000be','00000000-0000-0000-0000-0000000000f6',12,1,'cancelled','Fixture Host concluded helper parent',NULL,NULL,'00000000-0000-0000-0000-0000000000fe','host','fixture-host','conclude-2651c9540326b27d5157071a0d4ce4dc','2026-01-01T00:02:00.000Z');
CREATE TABLE workflow_integrations (
    integration_id        TEXT PRIMARY KEY,
    run_id                TEXT NOT NULL REFERENCES workflow_runs(run_id) ON DELETE RESTRICT,
    artifact_id           TEXT NOT NULL,
    strategy              TEXT NOT NULL,
    binding_sha256        TEXT NOT NULL,
    target_path           TEXT NOT NULL DEFAULT '',
    target_ref            TEXT NOT NULL DEFAULT '',
    target_repository_id  TEXT,
    target_checkout_id    TEXT,
    source_commit         TEXT,
    source_tree           TEXT,
    before_commit         TEXT,
    after_commit          TEXT,
    before_tree           TEXT,
    after_tree            TEXT,
    verification_json     TEXT NOT NULL,
    note                  TEXT,
    command_id            TEXT,
    actor_role            TEXT NOT NULL,
    actor_id              TEXT NOT NULL,
    created_at            TEXT NOT NULL,
    CHECK (actor_role IN ('host','lead','console','service','workflow','bridge')),
    UNIQUE(binding_sha256)
);
